<?php require 'includes/functions.php';require_login();$pdo=db();$uid=user()['id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(($_POST['action']??'')==='profile'){$pdo->prepare('UPDATE users SET full_name=?,email=?,mobile=?,address=? WHERE id=?')->execute([trim($_POST['full_name']),trim($_POST['email']),trim($_POST['mobile']),trim($_POST['address']),$uid]);$_SESSION['user']['email']=trim($_POST['email']);flash('success','Profile updated.');}if(($_POST['action']??'')==='password'){$q=$pdo->prepare('SELECT password FROM users WHERE id=?');$q->execute([$uid]);if(!password_verify($_POST['current']??'',$q->fetchColumn())||strlen($_POST['new']??'')<8)flash('danger','Use your correct current password and a new password of at least 8 characters.');else{$pdo->prepare('UPDATE users SET password=? WHERE id=?')->execute([password_hash($_POST['new'],PASSWORD_DEFAULT),$uid]);flash('success','Password changed.');}}go('profile.php');}$q=$pdo->prepare('SELECT * FROM users WHERE id=?');$q->execute([$uid]);$u=$q->fetch();$stats=[];foreach(['orders'=>'SELECT COUNT(*) FROM orders WHERE user_id=?','wishlist'=>'SELECT COUNT(*) FROM wishlist WHERE user_id=?'] as $key=>$sql){$q=$pdo->prepare($sql);$q->execute([$uid]);$stats[$key]=$q->fetchColumn();}$pageTitle='My Profile';require 'includes/header.php';require 'includes/navbar.php'; ?>
<main class="container my-5"><h1 class="section-title">My profile</h1><div class="row g-4"><div class="col-lg-8"><form method="post" class="card card-body"><input type="hidden" name="action" value="profile"><div class="row g-3"><div class="col-md-6"><label>Full name</label><input class="form-control" name="full_name" value="<?=e($u['full_name'])?>"></div><div class="col-md-6"><label>Username</label><input class="form-control" value="<?=e($u['username'])?>" disabled></div><div class="col-md-6"><label>Email</label><input class="form-control" name="email" type="email" value="<?=e($u['email'])?>"></div><div class="col-md-6"><label>Mobile</label><input class="form-control" name="mobile" value="<?=e($u['mobile'])?>"></div><div class="col-12"><label>Address</label><textarea class="form-control" name="address"><?=e($u['address'])?></textarea></div><div><button class="btn btn-dark">Save profile</button></div></div></form><form method="post" class="card card-body mt-3"><input type="hidden" name="action" value="password"><h5>Change password</h5><div class="row g-2"><div class="col-md"><input class="form-control" type="password" name="current" placeholder="Current password"></div><div class="col-md"><input class="form-control" type="password" name="new" placeholder="New password (8+ chars)"></div><div class="col-md-auto"><button class="btn btn-outline-dark">Change</button></div></div></form></div><div class="col-lg-4"><div class="card card-body"><h5><?=e($u['full_name'])?></h5><p class="text-muted">Member since <?=date('M Y',strtotime($u['created_at']))?></p><p><b><?=$stats['orders']?></b> orders<br><b><?=$stats['wishlist']?></b> wishlist items</p><a href="<?=base('addresses.php')?>">Manage addresses</a></div></div></div></main><?php require 'includes/footer.php'; ?>
